"""Supplement locked evaluation with explicitly separated historical tables and teacher analysis."""
from common import *
from evaluate_amended import KEYS,NAMES,BASE,state,cfg_for

def sel(rows,**kw):return [r for r in rows if all(r[k]==v for k,v in kw.items())]
def md(rows):
 if not rows:return '(Unavailable)\n'
 cols=list(rows[0]);return '| '+' | '.join(cols)+' |\n| '+' | '.join(['---']*len(cols))+' |\n'+''.join('| '+' | '.join(f'{r[c]:.4f}' if isinstance(r[c],float) else str(r[c]) for c in cols)+' |\n' for r in rows)
def main(out):
 out=Path(out);assert load(out/'13_Reports/METRICS_COMPLETE.json')['status']=='PASS';summary=read(out/'12_Source_Data/ALL_SETTING_METRICS.csv');historical=read(out/'12_Source_Data/HISTORICAL_FULL_PAD_REFERENCE.csv');classwise=read(out/'CLASSWISE_RESULTS.csv');cost=read(out/'MODEL_COMPLEXITY.csv');gain=read(out/'PAD_IMPROVEMENTS_BY_MODEL.csv');side=read(out/'SIX_MODEL_SIDE_BY_SIDE_RESULTS.csv');pairs=read(out/'12_Source_Data/ENHANCEMENT_PAIRED_COMPARISONS.csv');gates=[];historical_current=[]
 def point(k,c,d='PAD'):return sel(summary,model=k,condition=c,dataset=d,analysis_level='lesion_primary')[0]
 A=[];B=[];C=[];F=[]
 for k in KEYS:
  old=sel(historical,model=k,analysis_level='lesion_primary')[0];old_image=sel(historical,model=k,analysis_level='image_secondary')[0];assert int(old_image['support'])==1303;now=point(k,'E1');joint=point(k,'E2')
  A.append({'Model':NAMES[k],'Population':'Historical full PAD; POST-HOC historical reference','Declared lesions':old['support'],'Accuracy':float(old['accuracy']),'Macro-F1':float(old['macro_f1']),'Balanced accuracy':float(old['balanced_accuracy']),'MEL recall':float(old['MEL_recall']),'SCC recall':float(old['SCC_recall'])})
  for tab,p,cond in [(B,now,'E1 ISIC-only'),(C,joint,'E2 supervised joint')]:tab.append({'Model':NAMES[k],'Experiment':cond,'Declared lesions':p['support'],'Accuracy':float(p['accuracy']),'Macro-F1':float(p['macro_f1']),'Balanced accuracy':float(p['balanced_accuracy']),'MEL recall':float(p['MEL_recall']),'SCC recall':float(p['SCC_recall'])})
  historical_current.append({'model':k,'model_name':NAMES[k],'historical_full_PAD_lesions':old['support'],'historical_full_PAD_images':int(old_image['support']),'historical_full_PAD_accuracy':old['accuracy'],'historical_full_PAD_macro_f1':old['macro_f1'],'historical_full_PAD_balanced_accuracy':old['balanced_accuracy'],'current_fixed_PAD_images':261,'current_fixed_PAD_lesions':now['support'],'current_fixed_PAD_E1_accuracy':now['accuracy'],'current_fixed_PAD_E1_macro_f1':now['macro_f1'],'current_fixed_PAD_E1_balanced_accuracy':now['balanced_accuracy'],'comparison_status':'Descriptive different populations; no paired difference or adaptation effect computed'})
  for cond in ['E1','E2']:
   for cl in ['MEL','SCC']:
    r=sel(classwise,model=k,condition=cond,dataset='PAD',analysis_level='lesion_primary',**{'class':cl})[0];F.append({'Model':NAMES[k],'Experiment':cond,'Class':cl,'Correct':r['correct'],'Total':r['support'],'Precision':float(r['precision']),'Recall':float(r['recall']),'F1':float(r['f1'])})
 for k in ['M5','M5-LR']:
  hs=[json.loads(l) for l in (out/f'03_E2_Training/{k}/history.jsonl').read_text().splitlines()]
  for h in hs:
   for cl in CLASSES:
    g=h['teacher_gate_by_class'][cl];loss=h['loss_components'];gates.append({'model':k,'model_name':NAMES[k],'epoch':h['epoch'],'class':cl,'accepted':g['accepted'],'presentations':g['training_presentations'],'acceptance':g['accepted']/g['training_presentations'] if g['training_presentations'] else 0,'ce':loss['ce'],'kd':loss['kd'],'JS':loss['consistency'],'kd_weighted':.5*loss['kd'],'JS_weighted':.1*loss['consistency'],'mean_gate_mass':loss['gate_mass'],'total':h['training_total_loss'],'teacher_sha256':state(out,k)['teacher_sha256'],'PAD_validation_lesion_macro_F1':h['PAD_validation']['lesion']['macro_f1'],'loss_scope':'epoch aggregate repeated across class rows; gate counts are class-specific'})
 write(out/'HISTORICAL_VS_CURRENT_PAD_RESULTS.csv',historical_current);write(out/'12_Source_Data/TEACHER_GATE_AND_LOSS.csv',gates)
 write(out/'12_Source_Data/ENHANCED_CONTROL_PLOT_DATA.csv',[*({'record_type':'test_metric',**r} for r in summary if r['model'] in ['M5','M5-LR']),*({'record_type':'training_history',**r} for r in gates)])
 H=[r for r in sel(pairs,analysis_level='lesion_primary') if r['comparison']=='M5-LR minus M5'];tables={'A_historical_full_PAD':A,'B_current_E1_PAD':B,'C_current_E2_PAD':C,'D_matched_PAD_improvement':sel(gain,analysis_level='lesion_primary'),'E_four_settings':side,'F_MEL_SCC':F,'G_efficiency':cost,'H_enhanced_LR_control':H}
 for name,rows in tables.items():write(out/f'05_Four_Setting_Comparisons/TABLE_{name}.csv',rows)
 gate_summary=[]
 for k in ['M5','M5-LR']:
  for cl in CLASSES:
   rs=sel(gates,model=k,**{'class':cl});accepted=sum(int(r['accepted']) for r in rs);n=sum(int(r['presentations']) for r in rs);gate_summary.append({'Model':NAMES[k],'Class':cl,'Accepted presentations':accepted,'Total presentations':n,'Acceptance':accepted/n if n else 0})
 write(out/'12_Source_Data/TEACHER_GATE_SUMMARY.csv',gate_summary)
 weight_rows=[{'Class':cl,'Standard E2 moderated weight':cfg_for(out,'M2')['class_weights'][j],'Enhanced inverse-frequency weight':cfg_for(out,'M5')['class_weights'][j]} for j,cl in enumerate(CLASSES)];write(out/'12_Source_Data/CLASS_WEIGHT_PROTOCOL_DIFFERENCES.csv',weight_rows)
 q=load(out/'00_Protocol/TEACHER_QUALIFICATION.json');auth=load(out/'00_Protocol/AMENDED_TEACHER_AUTHORIZATION.json');m3=point('M3','E2');enhanced=[]
 for k in ['M5','M5-LR']:
  p=point(k,'E2');s=state(out,k);hs=[json.loads(l) for l in (out/f'03_E2_Training/{k}/history.jsonl').read_text().splitlines()];best=hs[s['best_epoch']-1];enhanced.append({'Model':NAMES[k],'Best additional epoch':s['best_epoch'],'Stop additional epoch':s['epochs'],'PAD validation F1':s['best_PAD_validation_lesion_F1'],'PAD test F1':float(p['macro_f1']),'PAD test minus joint M3 F1 pp':100*(float(p['macro_f1'])-float(m3['macro_f1'])),'Training seconds':s['training_seconds'],'Best-epoch CE':best['loss_components']['ce'],'Best-epoch weighted KD':.5*best['loss_components']['kd'],'Best-epoch weighted JS':.1*best['loss_components']['consistency']})
 report=f'''# Enhanced-model teacher analysis\n\nAmendment: {auth['amendment_id']}. Original qualification **FAILED**: frozen M4 validation macro-F1 {q['teacher_validation_F1']:.6f} versus joint M3 {q['student_validation_F1']:.6f}. The teacher is permitted under an explicit post-hoc exploratory amendment; it never qualified under the original superior-teacher hypothesis.\n\n{md(enhanced)}\n## Actual training guidance\n\n{md(gate_summary)}\nGate acceptance uses only training views and labels with the original confidence, entropy, agreement and correctness tests. The CSV also records actual KD/JS scales and mean reliability mass by epoch; low or zero accepted mass is reported as measured. Acceptance or nonzero gradients do not prove useful causal guidance. The same teacher checkpoint was frozen for both runs.\n\n## Controlled comparison and attribution\n\n{md(sel(H,dataset='PAD',metric='macro_f1'))}\nThe fixed standard-versus-enhanced supervised weighting differs as recorded below. All values use training data only. Domain-balanced resampling changes effective presentation frequencies; these weights cannot be interpreted as an isolated teacher intervention.\n\n{md(weight_rows)}\nThe M5-LR sensitivity control changes head/backbone rates from1e-4/1e-5to1e-5/1e-6. Parents, exact views/order, class weights, gates, losses, seed and selection rule match; realized stopping budgets can differ. There is **no matched joint-domain M5-without-teacher ablation**. Any M5-versus-M3 gain or loss is confounded by additional training, two views, different supervised weights and initialization policy. Neither a positive metric difference nor accepted teacher guidance proves the teacher caused an improvement. Negative results remain part of the study.\n\nAll PAD findings are POST-HOC EXPLORATORY. Full-PAD historical source-only scores use a different population and are not substituted into paired current-test effects. Seven melanoma and28SCCdeclared testlesions limit sensitivity estimates. These experiments do not establish novelty, external independence or clinical suitability.\n'''
 with (out/'ENHANCED_MODEL_TEACHER_ANALYSIS.md').open('x') as f:f.write(report)
 write(out/'CLASSWISE_COMPARISON.csv',classwise);write(out/'MODEL_EFFICIENCY.csv',cost)
 (out/'05_Four_Setting_Comparisons/HISTORICAL_POPULATION_WARNING.md').write_text('Historical full-PAD E1 and current fixed-PAD E1 are different evaluation populations. Their juxtaposition is descriptive only. Compute E2-minus-E1 differences only on the current identical261image/205declared-lesion fixed test set. No historical full-PAD versus current E2 difference is an adaptation effect.\n')
 dump(out/'13_Reports/SUPPLEMENTAL_TABLES_COMPLETE.json',{'status':'PASS','tables':list(tables),'historical_population_distinguished':True,'teacher_original_qualified':False,'amendment_id':auth['amendment_id']});print('Historical/current tables and weaker-teacher analysis complete',flush=True)
if __name__=='__main__':main(ROOT/sys.argv[1])
